{
  "predictions": [
    {
      "graph_embedding": [0.123456, -0.234567, ...],
      "block_embedding": [[0.345678, -0.456789, ...], ...],
      "atom_embedding": [[0.567890, -0.678901, ...], ...]
    }
  ]
